def lesson(q):
 topic=q['topic']
 if topic in ['Angular speed and radial acceleration','Friction and limiting circular motion','Horizontal circles on smooth surfaces']:return 'horizontal'
 if topic in ['Conical pendulums and linked particles','Elastic strings and circular motion']:return 'conical'
 if topic in ['Vertical circles: energy and radial forces','Changes of centre and light rods']:return 'vertical'
 if topic=='Slack strings and loss of contact':return 'contact'
 assert topic in ['Circular motion followed by a projectile','Circular motion and collisions'];return 'stages'


